import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Group from 'flarum/common/models/Group';
import GroupBadge from 'flarum/common/components/GroupBadge';
export default class RecipientGroupSettings extends Component {
  view() {
    const parsed = JSON.parse(this.attrs.value || '[]');
    const selected = Array.isArray(parsed) ? parsed.map(Number) : [];
    const groups = app.store.all('groups').filter(group => ![Group.GUEST_ID, Group.MEMBER_ID].includes(group.id()));
    return m("div", {
      className: "Form-group RecipientGroupSettings"
    }, m("label", null, app.translator.trans('flarum-messages.admin.settings.recipient_groups_label')), m("p", {
      className: "helpText"
    }, app.translator.trans('flarum-messages.admin.settings.recipient_groups_help')), groups.map(group => m("label", {
      className: "checkbox",
      key: group.id()
    }, m("input", {
      type: "checkbox",
      "data-group": group.id(),
      checked: selected.includes(Number(group.id())),
      onchange: () => {
        const id = Number(group.id());
        this.attrs.onchange(JSON.stringify(selected.includes(id) ? selected.filter(value => value !== id) : [...selected, id]));
      }
    }), m(GroupBadge, {
      group: group
    }), " ", group.namePlural())));
  }
}
flarum.reg.add('flarum-messages', 'admin/components/RecipientGroupSettings', RecipientGroupSettings);